    "파밍 자원 2배 획득 완료!": "2x Farmed Resources Claimed!",
    "파밍 자원 2배 획득": "2x Farmed Resources",
    "⚒️ 단조 스탯 편차(±30%) & [저주받은 장비] 정화 의식 및 5분 보존": "⚒️ Forge Stat Variance (±30%), Cursed Gear Cleansing & 5-Min Retention",
    "📖 마도서(스킬북) 연독 & 전직 스킬 100% 보존 & 에테르 공방 제작": "📖 Grimoire Inscription, Skill Preservation & Alchemy Crafting",
    "⚠️ 마물 차징(Charging) 메커니즘 & 브레이크(Break) 필수 수칙": "⚠️ Monster Charging Mechanism & Essential Break Protocols",
    "📜 심연의 백과(Codex) 컬렉션 봉헌 & 등록 우선순위 시스템": "📜 Abyssal Codex Collection Inscription & Priority System",
