    "'{0}'에 대한 검색 결과가 없습니다.": "No search results found for '{0}'.",
    "다른 키워드나 명칭을 입력해 보세요.": "Try searching with different keywords or names.",
    "검색어 초기화": "Reset Search",
    "전투 중 특정 전술 행동 시 획득, 5개 완충 시 궁극기로 FEVER 폭발": "Earned from tactical actions; fills 5 slots to unleash FEVER Ultimate synergy",
    "💡 전투 중 마물의 스킬이나 아군 장비/스킬의 효과로 해당 상태이상이 부여됩니다. 상태이상 지속 턴 수 동안 해당 패널티 또는 이로운 효과가 틱마다 적용됩니다.": "Applied during battle via enemy skills or ally gear. Penalties or buffs tick each turn for the duration.",
    "💡 적에게 {0} 상태가 부여되어 있을 때, 해당 태그가 부여된 스킬이나 기본 공격을 가하면 즉시 연계 콤보가 폭발합니다.": "When target is afflicted with {0}, hitting with a matching skill or basic attack triggers an immediate combo burst.",
    "전투 중 해당 조건이 달성되면 파티 공용 FEVER 게이지 슬롯에 뱃지가 즉시 적립됩니다.": "When conditions are met during combat, badges are banked into the shared FEVER gauge slots.",
    "★ 뱃지가 5개 가득 찼을 때 영웅이 궁극기를 발동하면 조합에 따른 강력한 시너지가 폭발합니다.": "When 5 badges are full, casting an Ultimate triggers a powerful synergy based on the badge combination.",
    "🔄 5개가 채워진 상태에서 새 뱃지를 얻으면 맨 앞의 오래된 뱃지가 밀려나며 실시간으로 최종 시너지가 갱신됩니다.": "At 5 badges, gaining a new badge pushes out the oldest one, updating final synergy in real time.",
    "⚠️ 비적합 클래스가 장착/사용 시 전투 중 위력이 50% 반감됩니다.": "⚠️ Equipping or using with an incompatible class reduces combat effectiveness by 50%.",
    "💡 성채 용병 관리 창에서 용병에게 전수하여 새로운 액티브 스킬 슬롯을 개방할 수 있습니다.": "💡 Teach to a mercenary in Citadel Mercenary Management to unlock an active skill slot.",
    "특수 및 기타 클래스": "Special & Other Classes",
    "기타 전직 및 특수 역할군": "Other Promotions & Special Roles",
    "기타 특수 직업": "Other Special Classes",
    "시작 클래스(Tier 0) ➔ 1차 전직(Tier 1) ➔ 2차 각성(Tier 2) ➔ 👑 3차 초월(Tier 3)": "Base Class (Tier 0) ➔ 1st Promotion (Tier 1) ➔ 2nd Awakening (Tier 2) ➔ 👑 3rd Transcendence (Tier 3)",
    "전투 중 마물의 스킬이나 아군 장비/스킬의 효과로 해당 상태이상이 부여됩니다. 상태이상 지속 턴 수 동안 해당 패널티 또는 이로운 효과가 틱마다 적용됩니다.": "Inflicted during combat via monster skills or ally equipment/skill effects. The corresponding penalty or boon applies every turn tick for the effect duration.",
    "상태이상 스킬 연계 콤보 메커니즘": "Status Effect Skill Synergy Combo Mechanism",
    "전술 운용 팁:": "Tactical Tip:",
    "{0}을 착용한 영웅은 기본 공격 및 관련 전투 행동 시 위 고유 메커니즘이 상시 적용됩니다. 시너지 효과를 가진 클래스와 조합하면 전투 효율이 극대화됩니다.": "Heroes equipping {0} will always apply the above unique mechanism during basic attacks and related actions. Synergizes greatly with compatible classes.",
    "최대 {0}단계까지 증축 가능하며, 레벨이 상승함에 따라 생산량이 비약적으로 증가하거나 새로운 제작 레시피 및 특수 기능이 해금됩니다. 시설 Lv.4부터는 골드 또는 식량 등의 유지비가 부과될 수 있습니다.": "Can be expanded up to Lv.{0}. As level increases, production increases drastically, and new crafting recipes or features unlock. Maintenance costs such as Gold or Food may apply from Lv.4.",
    "적에게 {0} 상태가 부여되어 있을 때, 해당 태그가 부여된 스킬이나 기본 공격을 가하면 즉시 연계 콤보가 폭발합니다.": "When the enemy is afflicted with {0}, attacking with a skill or attack bearing this tag immediately triggers this combo synergy.",
