    "공격력 +52, 치명타율 +10%, 방어관통 25%, 고유스킬 [파멸 강타] 부여 (기본 공격 대체)": "ATK +52, Crit Rate +10%, Armor Pen 25%, Grants unique skill [Ruin Smash] (Replaces basic attack)",
