    "빛의 정의가 함께하길! 정화하라!": "光の正義と共に！浄化せよ！",
    "\"빛의 정의가 함께하길! 정화하라!\"": "「光の正義と共に！浄化せよ！」",
    "지금이다! 뼈까지 부숴주마!": "今だ！骨まで砕いてやる！",
    "\"지금이다! 뼈까지 부숴주마!\"": "「今だ！骨まで砕いてやる！」",
