    "신성한 성화. 목재를 공헌하여 생산량 +15%, 전투 EXP +20%, 영지 용병 지속 재생 온기 버프를 활성화합니다.": "神聖なる聖火。木材を捧げて生産量+15%、戦闘EXP+20%、領地傭兵持続再生の温もりバフを有効化します。",
