    "[단일 결투] 적 1체에게 170% 물리 관통 피해 및 공격력 20% 감소": "[単体決闘] 敵1体に170%物理貫通ダメージ＆攻撃力20%減少。",
    "자신의 회피율을 2턴간 40% 증가시키고 적중 시 100% 반격 태세 취함": "自身の回避率を2ターン40%増加させ、被弾時100%反撃の構えをとる。",
    "[원거리 마법] 적 1체에게 130% 화염 피해 및 2턴 화상": "[遠距離魔法] 敵1体に130%火炎ダメージ＆2ターン火傷付与。",
