    "[광역 마법] 적 전체에게 110% 화염 폭발 피해 및 화상 중첩": "[広域魔法] 敵全体に110%火炎爆発ダメージ＆火傷スタック。",
    "적 1체를 1턴간 완전 결빙(기절)시키고 150% 냉기 피해": "敵1体を1ターン完全凍結（気絶）させ150%冷気ダメージ。",
