    "아군 전체의 쿨다운을 1턴 감소시키고 공격력 20% 버프": "味方全体のクールダウンを1ターン短縮し攻撃力+20%バフ。",
    "단일 아군의 체력을 시전자 마법력 비례 150% 치유": "単体味方のHPを詠唱者の魔法力比例150%回復。",
