    "자신의 체력 15%를 소모하여 공격력 50% 극대화 (3턴)": "自身のHP15%を消費し攻撃力を3ターン50%極大化。",
    "[전열/중열 특화] 적 1체에게 180% 맹렬한 검격 및 방어력 30% 파쇄": "[前衛/中衛特化] 敵1体に180%の猛烈な剣撃＆防御力30%破砕。",
