    "패황의 포효: 적 전체의 공격력을 2턴간 30% 약화시키고 아군 전체 공격력 20% 증가": "覇皇の咆哮: 敵全体の攻撃力を2ターン30%弱化、味方全体の攻撃力を20%増加。",
