    "불타는 적을 둔기로 짓이겨 고열을 순간 압축 폭발시킵니다. 타겟에게 40% 추가 화염 피해 및 주변 적들에게 35% 파편 피해": "燃える敵を鈍器で粉砕し高熱を圧縮爆発。対象に40%追加火炎ダメージ＆周囲敵に35%破片ダメージ",
