    "아군 전체의 모든 디버프를 즉시 정화하고 3턴간 매 턴 체력 9% 회복 및 디버프 면역 결계를 전개합니다.": "味方全体のデバフを即時浄化、3ターン毎ターンHP9%回復＆デバフ免疫結界を展開。",
    "2턴간 아군 전체 공격력 46% 상승 및 치명타율 20% 증가. 선포 후 자신은 HP 20% 희생.": "2ターン味方全体攻撃力46%上昇＆会心率20%増加。発動後自身はHP20%犠牲。",
    "자신에게 최대 체력 50%의 난공불락 방벽을 전개하고 2턴간 적들의 모든 공격을 도발": "自身に最大HP50%の難攻不落防壁を展開し2ターン敵の全攻撃を挑発。",
