    "아군 전체에게 1턴간 피해를 무효화하는 절대 결계를 전개하고, 2턴간 파티 전체가 받는 피해를 50% 경감합니다.": "味方全体に1ターン無敵絶対結界を展開、2ターン味方の被ダメージを50%軽減。",
