    "사망 임박(사경) 상태인 아군 1명을 부활시켜 체력 1로 소생시킵니다. (사망/사경 아군 없을 시 최저 체력 아군 115% 치유)": "死線状態の味方1名をHP1で蘇生させる（該当者がいない場合は最低HP味方を115%治療）。",
    "적 전체에 120% 대검 충격파를 가해 2턴간 공격력을 30% 약화시키고 모든 아군에게 최대 HP 25% 보호막을 부여합니다.": "敵全体に120%大剣衝撃波で2ターン攻撃力30%弱化＆味方全員に最大HP25%シールドを付与。",
    "[후열 저격] 시공간을 가르는 파멸 탄환을 발사하여 방어력을 100% 관통하고 280% 위력으로 공격합니다. (체력 40% 이하 대상 처형)": "[後衛狙撃] 時空を穿つ破滅弾で防御力100%貫通の威力280%攻撃（HP40%以下の対象を処刑）。",
    "아군 전체에게 영웅 최대 HP 50%의 보호막을 3턴간 전개하고, 2턴간 모든 피격에 130% 상시 반격 태세에 돌입합니다.": "味方全体に最大HP50%シールドを3ターン展開＆2ターン被弾時130%常時反撃態勢に突入。",
    "[전열 특화] 적 1체에게 260% 신성 물리/마법 복합 피해를 입히고 가한 피해의 100%만큼 최저 HP 아군을 치유합니다.": "[前衛特化] 敵1体に260%神聖複合ダメージ＆与ダメージの100%分最低HP味方を治癒。",
    "적 전체에 200% 신성 강타를 가하고, 가한 피해량만큼 파티 전원 체력을 회복하며, 사망/사경 상태의 아군을 체력 1로 즉시 부활시킵니다.": "敵全体に200%神聖強打＆与ダメージ分味方全体回復＆死亡/死線味方をHP1で即時復活。",
    "[전열 특화] 전열 적에게 280% 물리 참격을 가하고 2턴간 적의 공격력을 35% 감소시키며 가한 피해의 30%를 흡혈합니다.": "[前衛特化] 前衛に280%物理斬撃＆2ターン敵攻撃力35%減少＆与ダメージの30%を吸血。",
    "자신에게 2턴간 [은신]을 부여하고 다음 공격 치명타율 100% 확정 및 치명타 피해 80% 추가 증폭 버프를 획득합니다.": "自身に2ターン[潜伏]付与＆次の攻撃確定会心100%＆会心ダメージ+80%追加増幅バフを獲得。",
