    "터치 시 대화창이 닫히며 자유롭게 용병 후보들을 검토하고 고용하실 수 있습니다.": "タップすると対話が閉じ、自由に候補を検討して雇用できます。",
    "👑 [튜토리얼 완수] 첫 심연 정찰을 완벽히 마치고 정식 지휘관으로 임명되었습니다! 영지 시설을 발전시켜 심연을 정복하십시오!": "👑 [チュートリアル完了] 初の深淵偵察を見事に終え、正式な指揮官に任命されました！ 領地施設を発展させ深淵を征服してください！",
