    "심연 채비실 바로가기 (강하 준비)": "深淵準備室へ (降下準備)",
    "3인 원정대 편성 완료! 채비실에서 보급품을 챙기고 침식 회랑 1층 강하를 시작하세요!": "3人遠征隊の編成完了！ 準備室で補給品を整え、浸食の回廊1階への降下を開始してください！",
